const body = $json.body || $json;

// 1. Verifica evento e tipo de mensagem
const evento = body.event || '';
const msgType = body.message_type || '';
const content = (body.content || '').toString();
const conv = body.conversation || {};
const convId = conv.id || body.conversation_id;
const sender = body.sender || {};
const isPrivate = body.private === true;

// 2. Se for mensagem privada da equipe ou mensagem enviada pelo próprio robô, ignora
if (isPrivate || msgType === 'outgoing') {
  return [];
}

// 3. Verifica se a mensagem contém os termos do Módulo 1 / Apostila
const texto = content.toLowerCase();
const ehLeadCurso = texto.includes('apostila') || 
                    texto.includes('módulo 1') || 
                    texto.includes('modulo 1') || 
                    texto.includes('curso n8n') ||
                    texto.includes('cupom');

if (!ehLeadCurso || !convId) {
  return [];
}

// 4. Trata nome do cliente
let nome = (sender.name || '').toString().trim();
if (!nome || nome.includes('+') || nome.toLowerCase().includes('visitante')) {
  nome = 'Amigo(a)';
}
const primeiroNome = nome.split(' ')[0];

return {
  json: {
    conv_id: convId,
    nome: primeiroNome,
    telefone: sender.phone_number || '',
    link_apostila: 'https://curson8n.agente3d.net',
    link_grupo_vip: 'https://chat.whatsapp.com/CLUu662jFtvL9r2ahPaOJa',
    cupom: 'VIP10'
  }
};

